ALTER TABLE usuarios ADD legal_version VARCHAR(255);
ALTER TABLE usuarios ADD consent_at DATETIME(6);
ALTER TABLE usuarios ADD marketing BIT NOT NULL DEFAULT 0;
CREATE TABLE v2_experiences(id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,owner_id BIGINT NOT NULL,title VARCHAR(120) NOT NULL,description VARCHAR(5000) NOT NULL,kind VARCHAR(255) NOT NULL,department VARCHAR(255),municipality VARCHAR(255),address VARCHAR(255),latitude DOUBLE,longitude DOUBLE,meeting_latitude DOUBLE,meeting_longitude DOUBLE,meeting_instructions VARCHAR(1500),whatsapp VARCHAR(255),image_url VARCHAR(255),rnt VARCHAR(255),cancellation_policy VARCHAR(3000),price DECIMAL(12,2),active BIT NOT NULL,FOREIGN KEY(owner_id) REFERENCES usuarios(id));
CREATE TABLE v2_slots(id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,experience_id BIGINT NOT NULL,date DATE NOT NULL,time VARCHAR(255),capacity INT NOT NULL,version BIGINT,UNIQUE KEY slot_unique(experience_id,date,time),FOREIGN KEY(experience_id) REFERENCES v2_experiences(id));
CREATE TABLE v2_bookings(id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,experience_id BIGINT NOT NULL,slot_id BIGINT NOT NULL,user_id BIGINT NOT NULL,owner_id BIGINT,people INT NOT NULL,total DECIMAL(12,2),status VARCHAR(255),payment_status VARCHAR(255),title VARCHAR(120),reference VARCHAR(255),request_key VARCHAR(255) NOT NULL UNIQUE,created_at DATETIME(6),date DATE,end_date DATE,legal_version VARCHAR(255),meeting_latitude DOUBLE,meeting_longitude DOUBLE,meeting_instructions VARCHAR(1500),whatsapp VARCHAR(255),cancellation_snapshot VARCHAR(3000),version BIGINT,INDEX booking_user(user_id),INDEX booking_owner(owner_id),INDEX booking_slot(slot_id,status),FOREIGN KEY(experience_id) REFERENCES v2_experiences(id),FOREIGN KEY(slot_id) REFERENCES v2_slots(id),FOREIGN KEY(user_id) REFERENCES usuarios(id),FOREIGN KEY(owner_id) REFERENCES usuarios(id));
CREATE TABLE v2_notices(id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,title VARCHAR(255),message VARCHAR(1500),seen BIT NOT NULL,promotional BIT NOT NULL,created_at DATETIME(6),INDEX notice_user(user_id,id),FOREIGN KEY(user_id) REFERENCES usuarios(id));
CREATE TABLE v2_audit(id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,actor_id BIGINT,action VARCHAR(255),resource_id BIGINT,created_at DATETIME(6),FOREIGN KEY(actor_id) REFERENCES usuarios(id));
CREATE TABLE v2_privacy_requests(id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,user_id BIGINT,kind VARCHAR(255),detail VARCHAR(2000),status VARCHAR(255),created_at DATETIME(6),FOREIGN KEY(user_id) REFERENCES usuarios(id));
